// clone (one-way): encodes the request. txid must be 0.
static inline int32_t node_clone_encode(td_wire_msg_t *m, uint32_t txid, uint32_t node) {
  int32_t s = td_wire_begin(m, txid, TD_WIRE_REQUEST, 0, NODE_CLONE_ORDINAL, 8);
  if (s != CROI_OK) return s;
  if ((s = td_wire_store_handle(m, 0, node)) != CROI_OK) return s;
  return CROI_OK;
}

// clone: sends the one-way request.
static inline int32_t node_clone(uint32_t channel, td_wire_msg_t *buf, uint32_t node) {
  int32_t s = node_clone_encode(buf, 0, node);
  if (s != CROI_OK) return s;
  return (int32_t)croi_channel_write(channel, 0, buf->bytes, buf->byte_count, buf->handles, buf->handle_count);
}

// changed (event): decodes it.
static inline int32_t node_changed_decode(const td_wire_msg_t *m, node_ipc_change_t *change) {
  td_wire_reader_t rd, *r = &rd;
  int32_t s = CROI_OK;
  uint64_t v;
  (void)s;
  (void)v;
  td_wire_arena_t *a = NULL;
  (void)a;
  if (td_wire_read_begin(r, m, 40) != CROI_OK) return TD_ERR_PROTOCOL;
  if ((s = node_ipc_change_decode(r, 0, a, &((*change)))) != CROI_OK) return s;
  return td_wire_read_end(r);
}

